text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="theme-color" content="#0c0e18">
  <meta name="description" content="Dune Line — an overnight train across the desert to Nova Meridian. Dinner under the stars, a private cabin, and arrival in a city of light.">
  <title>Dune Line — Wake in Neon</title>
  <style>
    :root {
      --night: #0c0e18;
      --night-soft: #141624;
      --night-raised: #191b2b;
      --paper: #f4f0e7;
      --paper-deep: #e9e2d6;
      --ink: #19171b;
      --coral: #ff805c;
      --coral-soft: #e9b797;
      --mint: #91e8d6;
      --violet: #b394ff;
      --white: #fffaf1;
      --muted-dark: #aaa8b4;
      --muted-light: #6f6961;
      --line-dark: rgba(255, 255, 255, 0.13);
      --line-light: #d8d0c3;
      --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
      --font-serif: Georgia, "Times New Roman", serif;
      --font-mono: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
    }

    *, *::before, *::after {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
      scroll-padding-top: 24px;
    }

    body {
      margin: 0;
      overflow-x: hidden;
      background: var(--night);
      color: var(--white);
      font-family: var(--font-sans);
      font-size: 16px;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    body.menu-open {
      overflow: hidden;
    }

    ::selection {
      background: var(--coral);
      color: var(--night);
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button, input, select {
      font: inherit;
    }

    button {
      color: inherit;
      cursor: pointer;
    }

    svg {
      display: block;
      max-width: 100%;
    }

    h1, h2, h3, p, figure, blockquote {
      margin-top: 0;
    }

    [hidden] {
      display: none !important;
    }

    :focus-visible {
      outline: 2px solid var(--coral);
      outline-offset: 4px;
    }

    .container {
      width: min(1180px, calc(100% - 96px));
      margin-inline: auto;
    }

    .section {
      padding: 112px 0;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .skip-link {
      position: fixed;
      z-index: 1000;
      top: 12px;
      left: 12px;
      padding: 10px 16px;
      border-radius: 6px;
      background: var(--paper);
      color: var(--ink);
      transform: translateY(-150%);
      transition: transform 180ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .eyebrow {
      display: flex;
      align-items: center;
      gap: 11px;
      margin-bottom: 20px;
      color: var(--coral);
      font-family: var(--font-mono);
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.15em;
      line-height: 1.4;
      text-transform: uppercase;
    }

    .eyebrow::before {
      width: 25px;
      height: 1px;
      background: currentColor;
      content: "";
    }

    .section-title {
      margin-bottom: 0;
      font-size: clamp(40px, 4.25vw, 56px);
      font-weight: 540;
      letter-spacing: -0.047em;
      line-height: 1.07;
    }

    .section-heading {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 80px;
      align-items: end;
    }

    .section-heading > p {
      max-width: 430px;
      margin: 0 0 4px auto;
      color: var(--muted-light);
      font-size: 16px;
      line-height: 1.75;
    }

    .btn {
      display: inline-flex;
      min-height: 52px;
      align-items: center;
      justify-content: center;
      gap: 18px;
      padding: 0 23px;
      border: 1px solid transparent;
      border-radius: 7px;
      background: transparent;
      font-size: 13px;
      font-weight: 650;
      letter-spacing: 0.01em;
      line-height: 1;
      transition: transform 180ms ease, background-color 180ms ease, border-color 180ms ease, color 180ms ease;
    }

    .btn svg {
      width: 17px;
      height: 17px;
      flex: 0 0 auto;
      transition: transform 180ms ease;
    }

    .btn-primary {
      background: var(--coral);
      color: #21120e;
      box-shadow: 0 10px 32px rgba(255, 128, 92, 0.13);
    }

    .btn-outline-light {
      border-color: rgba(255, 255, 255, 0.26);
      color: var(--white);
    }

    .btn-outline-dark {
      border-color: #a8a094;
      color: var(--ink);
    }

    .text-link {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 10px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.28);
      color: #dedbe2;
      font-size: 13px;
      font-weight: 550;
      transition: border-color 180ms ease, color 180ms ease;
    }

    .text-link svg {
      width: 15px;
    }

    @media (hover: hover) {
      .btn:hover {
        transform: translateY(-2px);
      }

      .btn:hover svg {
        transform: translateX(3px);
      }

      .btn-primary:hover {
        background: #ff9577;
      }

      .btn-outline-light:hover {
        border-color: var(--white);
        background: rgba(255, 255, 255, 0.06);
      }

      .btn-outline-dark:hover {
        border-color: var(--ink);
        background: rgba(25, 23, 27, 0.05);
      }

      .text-link:hover {
        border-color: var(--coral);
        color: var(--white);
      }
    }

    /* Navigation */
    .site-header {
      position: relative;
      z-index: 50;
      background: var(--night);
    }

    .navbar {
      position: relative;
      display: flex;
      height: 90px;
      align-items: center;
      border-bottom: 1px solid var(--line-dark);
    }

    .brand {
      display: inline-flex;
      flex: 0 0 auto;
      align-items: center;
      gap: 12px;
    }

    .brand-mark {
      width: 39px;
      height: 39px;
    }

    .brand-copy {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .brand-name {
      font-size: 14px;
      font-weight: 750;
      letter-spacing: 0.19em;
      line-height: 1.2;
    }

    .brand-sub {
      color: #85838f;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.24em;
      line-height: 1.3;
      text-transform: uppercase;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 33px;
      margin-left: auto;
      margin-right: 37px;
    }

    .nav-links > a {
      position: relative;
      padding: 12px 0;
      color: #b7b5c0;
      font-size: 12px;
      font-weight: 550;
      transition: color 180ms ease;
    }

    .nav-links > a::after {
      position: absolute;
      right: 0;
      bottom: 6px;
      left: 0;
      height: 1px;
      background: var(--coral);
      content: "";
      transform: scaleX(0);
      transform-origin: right;
      transition: transform 180ms ease;
    }

    @media (hover: hover) {
      .nav-links > a:hover {
        color: var(--white);
      }

      .nav-links > a:hover::after {
        transform: scaleX(1);
        transform-origin: left;
      }
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .nav-book {
      min-height: 42px;
      padding: 0 18px;
      font-size: 12px;
    }

    .mobile-book {
      display: none;
    }

    .nav-toggle {
      display: none;
      width: 42px;
      height: 42px;
      align-items: center;
      justify-content: center;
      border: 1px solid var(--line-dark);
      border-radius: 7px;
      background: transparent;
    }

    .nav-toggle-lines {
      position: relative;
      width: 18px;
      height: 12px;
    }

    .nav-toggle-lines::before,
    .nav-toggle-lines::after {
      position: absolute;
      left: 0;
      width: 18px;
      height: 1px;
      background: var(--white);
      content: "";
      transition: top 180ms ease, transform 180ms ease;
    }

    .nav-toggle-lines::before {
      top: 2px;
    }

    .nav-toggle-lines::after {
      top: 9px;
    }

    .nav-toggle[aria-expanded="true"] .nav-toggle-lines::before {
      top: 6px;
      transform: rotate(45deg);
    }

    .nav-toggle[aria-expanded="true"] .nav-toggle-lines::after {
      top: 6px;
      transform: rotate(-45deg);
    }

    /* Hero */
    .hero {
      position: relative;
      overflow: hidden;
      background:
        radial-gradient(circle at 82% 13%, rgba(139, 92, 180, 0.14), transparent 29%),
        radial-gradient(circle at 6% 65%, rgba(255, 128, 92, 0.05), transparent 27%),
        var(--night);
    }

    .hero::before {
      position: absolute;
      top: 0;
      bottom: 0;
      left: calc(50% - 590px);
      width: 1px;
      background: linear-gradient(transparent, rgba(255, 255, 255, 0.04), transparent);
      content: "";
      pointer-events: none;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 0.88fr 1.12fr;
      gap: 46px;
      align-items: center;
      padding: 58px 0 48px;
    }

    .hero-copy {
      position: relative;
      z-index: 2;
    }

    .hero h1 {
      margin: 23px 0 27px;
      font-size: clamp(58px, 6vw, 78px);
      font-weight: 540;
      letter-spacing: -0.058em;
      line-height: 1.01;
    }

    .hero h1 > span {
      display: block;
    }

    .hero h1 em {
      color: var(--coral-soft);
      font-family: var(--font-serif);
      font-weight: 400;
      letter-spacing: -0.045em;
    }

    .hero-lede {
      max-width: 445px;
      margin-bottom: 31px;
      color: #b4b1bd;
      font-size: 16px;
      line-height: 1.75;
    }

    .hero-actions {
      display: flex;
      align-items: center;
      gap: 26px;
    }

    .hero-facts {
      display: flex;
      flex-wrap: wrap;
      gap: 10px 20px;
      margin-top: 30px;
      color: #777582;
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .hero-facts span {
      display: inline-flex;
      align-items: center;
      gap: 20px;
    }

    .hero-facts span:not(:last-child)::after {
      width: 3px;
      height: 3px;
      border-radius: 50%;
      background: #5b5965;
      content: "";
    }

    .hero-visual {
      position: relative;
      min-width: 0;
    }

    .scene {
      position: relative;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 26px;
      background: #161526;
      box-shadow: 0 35px 90px rgba(0, 0, 0, 0.34);
      isolation: isolate;
    }

    .scene::after {
      position: absolute;
      inset: 0;
      z-index: 1;
      border-radius: inherit;
      box-shadow: inset 0 0 80px rgba(4, 5, 12, 0.22);
      content: "";
      pointer-events: none;
    }

    .desert-scene {
      width: 100%;
      height: auto;
    }

    .scene-badge,
    .scene-coordinate,
    .scene-caption {
      position: absolute;
      z-index: 3;
    }

    .scene-badge {
      top: 20px;
      left: 20px;
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 9px 12px;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 100px;
      background: rgba(10, 11, 22, 0.48);
      backdrop-filter: blur(12px);
      color: #e8e3eb;
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.12em;
    }

    .status-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--mint);
      box-shadow: 0 0 10px rgba(145, 232, 214, 0.8);
      animation: statusPulse 3s ease-in-out infinite;
    }

    .scene-coordinate {
      top: 28px;
      right: 23px;
      color: rgba(255, 255, 255, 0.52);
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.1em;
    }

    .scene-caption {
      right: 20px;
      bottom: 19px;
      left: 20px;
      display: grid;
      grid-template-columns: 1fr auto auto;
      gap: 20px;
      align-items: center;
      padding: 15px 17px;
      border: 1px solid rgba(255, 255, 255, 0.13);
      border-radius: 13px;
      background: rgba(8, 10, 18, 0.76);
      backdrop-filter: blur(15px);
    }

    .scene-caption small {
      display: block;
      margin-bottom: 3px;
      color: #8d8999;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .scene-caption strong {
      display: block;
      font-size: 12px;
      font-weight: 550;
      letter-spacing: 0.01em;
    }

    .mini-route {
      display: flex;
      width: 91px;
      align-items: center;
      gap: 5px;
    }

    .mini-route::before,
    .mini-route::after {
      width: 5px;
      height: 5px;
      flex: 0 0 auto;
      border: 1px solid #c5bfca;
      border-radius: 50%;
      content: "";
    }

    .mini-route span {
      height: 1px;
      flex: 1;
      background: linear-gradient(90deg, var(--coral) 62%, rgba(255, 255, 255, 0.22) 62%);
    }

    .scene-time {
      color: #d8d3dd;
      font-family: var(--font-mono);
      font-size: 10px;
    }

    .city-glow {
      animation: cityGlow 5s ease-in-out infinite alternate;
    }

    .star-pulse {
      animation: starPulse 4s ease-in-out infinite alternate;
    }

    @keyframes statusPulse {
      50% { opacity: 0.45; }
    }

    @keyframes cityGlow {
      from { opacity: 0.68; }
      to { opacity: 1; }
    }

    @keyframes starPulse {
      from { opacity: 0.35; }
      to { opacity: 0.9; }
    }

    .route-bar {
      display: grid;
      grid-template-columns: 1fr 1.15fr 1.15fr auto;
      gap: 30px;
      align-items: center;
      padding: 27px 0 30px;
      border-top: 1px solid var(--line-dark);
    }

    .route-place > span {
      display: block;
      margin-bottom: 4px;
      color: #716f7b;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .route-place strong {
      display: block;
      margin-bottom: 1px;
      font-size: 15px;
      font-weight: 550;
    }

    .route-place small {
      color: #8d8a96;
      font-size: 11px;
    }

    .route-track {
      display: grid;
      grid-template-columns: auto 1fr auto;
      gap: 8px;
      align-items: center;
    }

    .route-track > span {
      width: 6px;
      height: 6px;
      border: 1px solid #8a8693;
      border-radius: 50%;
    }

    .route-track > span:first-child {
      border-color: var(--coral);
      background: var(--coral);
      box-shadow: 0 0 12px rgba(255, 128, 92, 0.4);
    }

    .route-track-line {
      position: relative;
      height: 1px;
      background: repeating-linear-gradient(90deg, #55525f 0 5px, transparent 5px 10px);
    }

    .route-track-line svg {
      position: absolute;
      top: -9px;
      left: 52%;
      width: 20px;
      color: var(--coral-soft);
    }

    .route-track small {
      grid-column: 1 / -1;
      margin-top: 2px;
      color: #716f7b;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.11em;
      text-align: center;
      text-transform: uppercase;
    }

    .route-link {
      display: inline-flex;
      align-items: center;
      gap: 9px;
      color: #bbb7c2;
      font-size: 11px;
      white-space: nowrap;
    }

    .route-link svg {
      width: 14px;
      color: var(--coral);
    }

    /* Features */
    .paper {
      background: var(--paper);
      color: var(--ink);
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
      margin-top: 63px;
    }

    .feature-card {
      position: relative;
      padding: 29px 28px 27px;
      border: 1px solid var(--line-light);
      border-radius: 17px;
      background: rgba(255, 255, 255, 0.25);
      transition: background-color 200ms ease, transform 200ms ease, box-shadow 200ms ease;
    }

    @media (hover: hover) {
      .feature-card:hover {
        background: rgba(255, 255, 255, 0.58);
        box-shadow: 0 18px 45px rgba(58, 43, 28, 0.06);
        transform: translateY(-5px);
      }
    }

    .feature-top {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 31px;
    }

    .feature-icon {
      display: grid;
      width: 54px;
      height: 54px;
      place-items: center;
      border-radius: 13px;
      background: #e8ddcc;
      color: #9f503a;
    }

    .feature-icon svg {
      width: 29px;
      height: 29px;
    }

    .feature-number {
      color: #a29a8d;
      font-family: var(--font-mono);
      font-size: 10px;
      letter-spacing: 0.1em;
    }

    .feature-card h3 {
      margin-bottom: 12px;
      font-size: 22px;
      font-weight: 580;
      letter-spacing: -0.025em;
      line-height: 1.25;
    }

    .feature-card p {
      min-height: 102px;
      margin-bottom: 24px;
      color: var(--muted-light);
      font-size: 14px;
      line-height: 1.72;
    }

    .feature-note {
      display: flex;
      align-items: center;
      gap: 9px;
      padding-top: 18px;
      border-top: 1px solid var(--line-light);
      color: #827a70;
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .feature-note::before {
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: var(--coral);
      content: "";
    }

    /* Timetable */
    .timetable-section {
      padding: 104px 0 110px;
      background: var(--paper-deep);
      color: var(--ink);
    }

    .timetable-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 40px;
      margin-bottom: 39px;
    }

    .timetable-head .section-title {
      font-size: clamp(38px, 4vw, 52px);
    }

    .schedule-meta {
      padding-bottom: 4px;
      text-align: right;
    }

    .schedule-meta strong {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 11px;
      margin-bottom: 5px;
      font-size: 13px;
      font-weight: 600;
    }

    .schedule-meta strong svg {
      width: 17px;
      color: #a7543d;
    }

    .schedule-meta span {
      color: var(--muted-light);
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.09em;
      text-transform: uppercase;
    }

    .schedule-shell {
      overflow: hidden;
      border: 1px solid #d5ccbd;
      border-radius: 18px;
      background: #f8f4ed;
      box-shadow: 0 24px 55px rgba(58, 43, 28, 0.06);
    }

    .schedule-table {
      width: 100%;
      border-collapse: collapse;
      table-layout: fixed;
    }

    .schedule-table th {
      padding: 17px 20px;
      background: rgba(222, 213, 199, 0.37);
      color: #847c71;
      font-family: var(--font-mono);
      font-size: 9px;
      font-weight: 500;
      letter-spacing: 0.12em;
      text-align: left;
      text-transform: uppercase;
    }

    .schedule-table th:first-child,
    .schedule-table td:first-child {
      padding-left: 25px;
      width: 27%;
    }

    .schedule-table th:nth-child(2),
    .schedule-table th:nth-child(3) {
      width: 15%;
    }

    .schedule-table th:nth-child(4) {
      width: 13%;
    }

    .schedule-table th:nth-child(5) {
      width: 22%;
    }

    .schedule-table th:last-child,
    .schedule-table td:last-child {
      width: 8%;
      padding-right: 23px;
      text-align: right;
    }

    .schedule-table td {
      padding: 22px 20px;
      border-top: 1px solid #e0d8cc;
      vertical-align: middle;
      transition: background-color 180ms ease;
    }

    .schedule-table tr.popular-row td {
      background: #fff9ef;
    }

    @media (hover: hover) {
      .schedule-table tbody tr:hover td {
        background: #fffdf8;
      }
    }

    .service {
      display: flex;
      align-items: center;
      gap: 13px;
    }

    .service-icon {
      display: grid;
      width: 39px;
      height: 39px;
      flex: 0 0 auto;
      place-items: center;
      border: 1px solid #d8cfc1;
      border-radius: 10px;
      color: #9f513c;
    }

    .service-icon svg {
      width: 20px;
    }

    .service strong {
      display: block;
      margin-bottom: 2px;
      font-size: 13px;
      font-weight: 650;
    }

    .service small,
    .station {
      display: block;
      color: #898176;
      font-size: 10px;
    }

    .service-code {
      margin-right: 5px;
      color: #a19a90;
      font-family: var(--font-mono);
    }

    .time {
      display: block;
      margin-bottom: 1px;
      font-size: 24px;
      font-weight: 540;
      letter-spacing: -0.035em;
      line-height: 1.2;
    }

    .duration {
      font-family: var(--font-mono);
      font-size: 12px;
    }

    .availability {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      color: #69635c;
      font-size: 11px;
    }

    .availability::before {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: #6f9e80;
      content: "";
    }

    .availability.popular {
      color: #9d4d37;
    }

    .availability.popular::before {
      background: var(--coral);
    }

    .availability.limited::before {
      background: #c08c44;
    }

    .row-action {
      display: inline-grid;
      width: 38px;
      height: 38px;
      place-items: center;
      border: 1px solid #cfc5b6;
      border-radius: 50%;
      background: transparent;
      color: var(--ink);
      transition: background-color 180ms ease, color 180ms ease, transform 180ms ease;
    }

    .row-action svg {
      width: 15px;
    }

    @media (hover: hover) {
      .row-action:hover {
        background: var(--ink);
        color: var(--paper);
        transform: translateX(2px);
      }
    }

    .schedule-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 25px;
      padding: 18px 24px;
      border-top: 1px solid #ded5c8;
      background: rgba(231, 223, 211, 0.35);
      color: #827a70;
      font-size: 10px;
    }

    .schedule-footer span:first-child {
      display: inline-flex;
      align-items: center;
      gap: 8px;
    }

    .schedule-footer svg {
      width: 14px;
      flex: 0 0 auto;
    }

    /* Pricing */
    .pricing {
      position: relative;
      overflow: hidden;
      background:
        radial-gradient(circle at 88% 15%, rgba(135, 95, 184, 0.12), transparent 26%),
        radial-gradient(circle at 9% 86%, rgba(255, 128, 92, 0.06), transparent 24%),
        var(--night);
      color: var(--white);
    }

    .pricing .section-heading > p {
      color: var(--muted-dark);
    }

    .pricing-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      align-items: stretch;
      margin-top: 70px;
    }

    .price-card {
      position: relative;
      display: flex;
      min-height: 500px;
      flex-direction: column;
      padding: 31px 29px 29px;
      border: 1px solid rgba(255, 255, 255, 0.14);
      border-radius: 19px;
      background: rgba(255, 255, 255, 0.025);
    }

    .price-card.featured {
      border-color: var(--paper);
      background: var(--paper);
      color: var(--ink);
      box-shadow: 0 28px 70px rgba(0, 0, 0, 0.28);
      transform: translateY(-14px);
    }

    .popular-badge {
      position: absolute;
      top: -13px;
      left: 29px;
      padding: 6px 11px;
      border-radius: 100px;
      background: var(--coral);
      color: #25130e;
      font-family: var(--font-mono);
      font-size: 8px;
      font-weight: 700;
      letter-spacing: 0.13em;
      text-transform: uppercase;
    }

    .tier-kicker {
      margin-bottom: 12px;
      color: #817e8a;
      font-family: var(--font-mono);
      font-size: 9px;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .featured .tier-kicker {
      color: #8b8175;
    }

    .price-card h3 {
      margin-bottom: 0;
      font-size: 25px;
      font-weight: 550;
      letter-spacing: -0.025em;
    }

    .price {
      display: flex;
      align-items: end;
      gap: 8px;
      margin: 26px 0 26px;
      padding-bottom: 26px;
      border-bottom: 1px solid var(--line-dark);
    }

    .featured .price {
      border-color: var(--line-light);
    }

    .price-from {
      align-self: flex-start;
      margin-top: 9px;
      color: #8f8b98;
      font-family: var(--font-mono);
      font-size: 9px;
      text-transform: uppercase;
    }

    .currency {
      align-self: flex-start;
      margin: 8px 0 0 3px;
      color: #c8c3cd;
      font-size: 20px;
    }

    .featured .currency {
      color: #6e665d;
    }

    .amount {
      font-size: 53px;
      font-weight: 500;
      letter-spacing: -0.055em;
      line-height: 1;
    }

    .price-unit {
      margin-bottom: 4px;
      color: #8d8996;
      font-size: 10px;
    }

    .price-features {
      display: grid;
      gap: 14px;
      margin: 0 0 31px;
      padding: 0;
      list-style: none;
    }

    .price-features li {
      display: flex;
      align-items: flex-start;
      gap: 10px;
      color: #b8b4c0;
      font-size: 12px;
      line-height: 1.55;
    }

    .featured .price-features li {
      color: #635d56;
    }

    .price-features li::before {
      flex: 0 0 auto;
      margin-top: 1px;
      color: var(--coral);
      content: "✓";
      font-size: 13px;
      font-weight: 700;
    }

    .price-card .btn {
      width: 100%;
      margin-top: auto;
    }

    .price-caption {
      margin: 15px 0 0;
      color: #6f6c78;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.06em;
      text-align: center;
      text-transform: uppercase;
    }

    .featured .price-caption {
      color: #948b80;
    }

    .pricing-footnote {
      margin: 30px 0 0;
      color: #777481;
      font-size: 11px;
      text-align: center;
    }

    /* Testimonial */
    .testimonial {
      background: var(--paper);
      color: var(--ink);
      padding: 108px 0;
    }

    .testimonial-grid {
      display: grid;
      grid-template-columns: 235px 1fr;
      gap: 72px;
      align-items: center;
    }

    .postcard-note {
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    .postcard-stamp {
      display: grid;
      width: 166px;
      height: 166px;
      place-items: center;
      border: 1px solid #b6a897;
      border-radius: 50%;
      color: #8c6554;
      text-align: center;
      transform: rotate(-8deg);
    }

    .postcard-stamp::before {
      position: absolute;
      width: 150px;
      height: 150px;
      border: 1px dashed #c6b9a9;
      border-radius: 50%;
      content: "";
    }

    .postcard-stamp span {
      display: block;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.17em;
      line-height: 1.8;
      text-transform: uppercase;
    }

    .postcard-stamp strong {
      display: block;
      margin: 5px 0;
      font-family: var(--font-serif);
      font-size: 29px;
      font-weight: 400;
      letter-spacing: -0.04em;
      line-height: 1;
    }

    .postcard-note > small {
      margin-top: 25px;
      color: #8f867a;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.16em;
      text-transform: uppercase;
    }

    .quote-mark {
      height: 53px;
      color: var(--coral);
      font-family: var(--font-serif);
      font-size: 96px;
      line-height: 0.9;
    }

    .testimonial blockquote {
      margin-bottom: 32px;
      font-family: var(--font-serif);
      font-size: clamp(30px, 3.15vw, 42px);
      font-weight: 400;
      letter-spacing: -0.025em;
      line-height: 1.29;
    }

    .testimonial figcaption {
      display: flex;
      align-items: center;
      gap: 13px;
    }

    .avatar {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 50%;
      background: #dfb196;
      color: #4b2f25;
      font-family: var(--font-serif);
      font-size: 14px;
      font-style: italic;
    }

    .attribution strong {
      display: block;
      font-size: 12px;
      font-weight: 650;
    }

    .attribution span {
      display: block;
      color: #847b70;
      font-size: 10px;
    }

    /* Footer */
    .site-footer {
      background: #0a0c14;
      color: var(--white);
    }

    .footer-cta {
      position: relative;
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 50px;
      padding: 92px 0 88px;
      border-bottom: 1px solid var(--line-dark);
    }

    .footer-cta::after {
      position: absolute;
      right: 23%;
      bottom: 42px;
      width: 190px;
      height: 190px;
      border: 1px solid rgba(179, 148, 255, 0.09);
      border-radius: 50%;
      box-shadow: 0 0 80px rgba(179, 148, 255, 0.04);
      content: "";
      pointer-events: none;
    }

    .footer-cta h2 {
      position: relative;
      z-index: 1;
      margin-bottom: 18px;
      font-size: clamp(42px, 4.8vw, 62px);
      font-weight: 520;
      letter-spacing: -0.05em;
      line-height: 1.04;
    }

    .footer-cta p {
      max-width: 500px;
      margin-bottom: 0;
      color: #8f8c99;
      font-size: 14px;
    }

    .footer-cta .btn {
      position: relative;
      z-index: 2;
      flex: 0 0 auto;
      margin-bottom: 5px;
    }

    .footer-main {
      display: grid;
      grid-template-columns: 1.55fr 0.65fr 0.65fr 1fr;
      gap: 52px;
      padding: 57px 0 53px;
    }

    .footer-brand p {
      max-width: 265px;
      margin: 22px 0 0;
      color: #777481;
      font-size: 12px;
      line-height: 1.7;
    }

    .footer-column h3 {
      margin-bottom: 18px;
      color: #706d79;
      font-family: var(--font-mono);
      font-size: 9px;
      font-weight: 500;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .footer-column a,
    .footer-column p {
      display: block;
      margin: 0 0 10px;
      color: #aaa6b2;
      font-size: 11px;
      line-height: 1.7;
      transition: color 180ms ease;
    }

    @media (hover: hover) {
      .footer-column a:hover {
        color: var(--coral-soft);
      }
    }

    .footer-column .station-detail {
      color: #6e6b76;
      font-size: 10px;
    }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 30px;
      padding: 21px 0 25px;
      border-top: 1px solid var(--line-dark);
      color: #5f5c68;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    /* Booking dialog */
    .booking-dialog {
      width: min(520px, calc(100% - 32px));
      max-height: min(90vh, 760px);
      margin: auto;
      padding: 0;
      overflow: auto;
      border: 0;
      border-radius: 20px;
      background: var(--paper);
      color: var(--ink);
      box-shadow: 0 40px 120px rgba(0, 0, 0, 0.5);
    }

    .booking-dialog::backdrop {
      background: rgba(5, 6, 12, 0.78);
      backdrop-filter: blur(7px);
    }

    .dialog-panel {
      padding: 31px;
    }

    .dialog-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 25px;
      margin-bottom: 25px;
    }

    .dialog-header .eyebrow {
      margin-bottom: 10px;
      font-size: 9px;
    }

    .dialog-header h2 {
      margin-bottom: 0;
      font-size: 32px;
      font-weight: 550;
      letter-spacing: -0.04em;
      line-height: 1.15;
    }

    .dialog-close {
      display: grid;
      width: 36px;
      height: 36px;
      flex: 0 0 auto;
      place-items: center;
      border: 1px solid var(--line-light);
      border-radius: 50%;
      background: transparent;
      color: var(--ink);
    }

    .dialog-close svg {
      width: 15px;
    }

    .selected-fare {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 23px;
      padding: 15px 17px;
      border: 1px solid #ddd2c3;
      border-radius: 10px;
      background: #ece2d4;
    }

    .selected-fare span {
      color: #877b6e;
      font-family: var(--font-mono);
      font-size: 8px;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    .selected-fare strong {
      font-size: 12px;
      font-weight: 650;
    }

    .booking-form {
      display: grid;
      gap: 17px;
    }

    .form-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
    }

    .booking-form label {
      display: grid;
      gap: 7px;
      color: #746c62;
      font-size: 10px;
      font-weight: 600;
    }

    .booking-form input,
    .booking-form select {
      width: 100%;
      min-height: 47px;
      padding: 0 12px;
      border: 1px solid #cfc4b5;
      border-radius: 7px;
      outline: 0;
      background: #fffdf8;
      color: var(--ink);
      font-size: 12px;
    }

    .booking-form input:focus,
    .booking-form select:focus {
      border-color: #aa654d;
      box-shadow: 0 0 0 3px rgba(255, 128, 92, 0.14);
    }

    .booking-form .btn {
      width: 100%;
      margin-top: 4px;
    }

    .form-note {
      margin: -4px 0 0;
      color: #91887d;
      font-size: 9px;
      text-align: center;
    }

    .booking-success {
      padding: 19px 0 5px;
      text-align: center;
    }

    .success-icon {
      display: grid;
      width: 64px;
      height: 64px;
      margin: 0 auto 22px;
      place-items: center;
      border-radius: 50%;
      background: #e5d7c5;
      color: #9f503a;
    }

    .success-icon svg {
      width: 27px;
    }

    .booking-success h3 {
      margin-bottom: 10px;
      font-family: var(--font-serif);
      font-size: 30px;
      font-weight: 400;
    }

    .booking-success p {
      max-width: 360px;
      margin: 0 auto 23px;
      color: var(--muted-light);
      font-size: 12px;
    }

    .success-summary {
      margin-bottom: 24px;
      padding: 14px;
      border-top: 1px solid var(--line-light);
      border-bottom: 1px solid var(--line-light);
      color: #6f665c;
      font-family: var(--font-mono);
      font-size: 10px;
      line-height: 1.8;
    }

    /* Responsive */
    @media (max-width: 1100px) {
      .container {
        width: calc(100% - 64px);
      }

      .hero::before {
        left: 32px;
      }

      .hero-grid {
        gap: 32px;
      }

      .hero h1 {
        font-size: clamp(55px, 6.2vw, 68px);
      }

      .nav-links {
        gap: 24px;
        margin-right: 26px;
      }

      .feature-card {
        padding-inline: 23px;
      }

      .price-card {
        padding-inline: 24px;
      }
    }

    @media (max-width: 900px) {
      .nav-toggle {
        display: inline-flex;
      }

      .nav-links {
        position: absolute;
        top: 89px;
        right: 0;
        left: 0;
        display: none;
        margin: 0;
        padding: 15px 23px 23px;
        border: 1px solid var(--line-dark);
        border-top: 0;
        border-radius: 0 0 15px 15px;
        background: #151724;
        box-shadow: 0 24px 50px rgba(0, 0, 0, 0.35);
      }

      .nav-links.is-open {
        display: flex;
        flex-direction: column;
        align-items: stretch;
        gap: 0;
      }

      .nav-links > a {
        padding: 13px 0;
        border-bottom: 1px solid rgba(255, 255, 255, 0.07);
      }

      .nav-links > a::after {
        display: none;
      }

      .mobile-book {
        display: inline-flex;
        margin-top: 18px;
      }

      .nav-actions {
        margin-left: auto;
      }

      .hero-grid {
        grid-template-columns: 1fr;
        gap: 50px;
        padding: 65px 0 48px;
      }

      .hero-copy {
        max-width: 650px;
      }

      .hero h1 {
        font-size: 78px;
      }

      .hero-lede {
        max-width: 510px;
      }

      .hero-visual {
        width: 100%;
        max-width: 740px;
        margin-inline: auto;
      }

      .route-bar {
        grid-template-columns: 1fr 1.1fr 1fr;
      }

      .route-link {
        grid-column: 1 / -1;
        justify-self: start;
      }

      .section {
        padding: 88px 0;
      }

      .section-heading {
        gap: 45px;
      }

      .features-grid {
        gap: 16px;
      }

      .feature-card {
        padding: 24px 20px;
      }

      .feature-card p {
        min-height: 126px;
      }

      .schedule-table th,
      .schedule-table td {
        padding-right: 12px;
        padding-left: 12px;
      }

      .schedule-table th:first-child,
      .schedule-table td:first-child {
        padding-left: 18px;
      }

      .service-icon {
        display: none;
      }

      .price-card {
        min-height: 520px;
        padding-inline: 20px;
      }

      .amount {
        font-size: 46px;
      }

      .testimonial-grid {
        grid-template-columns: 175px 1fr;
        gap: 45px;
      }

      .postcard-stamp {
        width: 145px;
        height: 145px;
      }

      .postcard-stamp::before {
        width: 130px;
        height: 130px;
      }

      .footer-main {
        grid-template-columns: 1.4fr 0.8fr 0.8fr;
      }

      .footer-column:last-child {
        grid-column: 1 / -1;
        padding-top: 10px;
      }
    }

    @media (max-width: 760px) {
      .section-heading {
        grid-template-columns: 1fr;
        gap: 25px;
      }

      .section-heading > p {
        max-width: 540px;
        margin-left: 0;
      }

      .features-grid {
        grid-template-columns: 1fr;
        gap: 15px;
        margin-top: 43px;
      }

      .feature-card {
        padding: 26px;
      }

      .feature-top {
        margin-bottom: 22px;
      }

      .feature-card p {
        min-height: 0;
      }

      .timetable-section {
        padding: 82px 0;
      }

      .timetable-head {
        align-items: flex-start;
        flex-direction: column;
        gap: 22px;
      }

      .schedule-meta {
        text-align: left;
      }

      .schedule-meta strong {
        justify-content: flex-start;
      }

      .schedule-shell {
        overflow: visible;
        border: 0;
        border-radius: 0;
        background: transparent;
        box-shadow: none;
      }

      .schedule-table,
      .schedule-table tbody {
        display: block;
      }

      .schedule-table thead {
        display: none;
      }

      .schedule-table tr {
        position: relative;
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 18px 22px;
        margin-bottom: 13px;
        padding: 23px;
        border: 1px solid #d5ccbd;
        border-radius: 14px;
        background: #f8f4ed;
      }

      .schedule-table tr.popular-row {
        background: #fff9ef;
      }

      .schedule-table td,
      .schedule-table td:first-child,
      .schedule-table td:last-child {
        display: block;
        width: auto;
        padding: 0;
        border: 0;
        background: transparent !important;
        text-align: left;
      }

      .schedule-table td::before {
        display: block;
        margin-bottom: 5px;
        color: #978d80;
        font-family: var(--font-mono);
        font-size: 8px;
        letter-spacing: 0.11em;
        content: attr(data-label);
        text-transform: uppercase;
      }

      .schedule-table td:first-child {
        grid-column: 1 / -1;
        padding-bottom: 16px;
        border-bottom: 1px solid #e0d7ca;
      }

      .schedule-table td:first-child::before,
      .schedule-table td:last-child::before {
        display: none;
      }

      .service-icon {
        display: grid;
      }

      .schedule-table td:last-child {
        position: absolute;
        right: 20px;
        bottom: 21px;
      }

      .schedule-table td:nth-child(5) {
        padding-right: 45px;
      }

      .time {
        font-size: 27px;
      }

      .schedule-footer {
        align-items: flex-start;
        flex-direction: column;
        gap: 7px;
        margin-top: 22px;
        padding: 0;
        border: 0;
        background: transparent;
        line-height: 1.6;
      }

      .pricing-grid {
        grid-template-columns: 1fr;
        max-width: 560px;
        gap: 19px;
        margin: 52px auto 0;
      }

      .price-card {
        min-height: 0;
        padding: 30px;
      }

      .price-card.featured {
        margin: 8px 0;
        transform: none;
      }

      .price-features {
        margin-bottom: 28px;
      }

      .testimonial-grid {
        grid-template-columns: 1fr;
        gap: 45px;
      }

      .postcard-note {
        align-items: flex-start;
        flex-direction: row;
        gap: 26px;
      }

      .postcard-stamp {
        width: 120px;
        height: 120px;
        flex: 0 0 auto;
      }

      .postcard-stamp::before {
        width: 107px;
        height: 107px;
      }

      .postcard-stamp strong {
        font-size: 23px;
      }

      .postcard-stamp span {
        font-size: 6px;
      }

      .postcard-note > small {
        max-width: 110px;
        margin-top: 35px;
        line-height: 1.8;
      }

      .footer-cta {
        align-items: flex-start;
        flex-direction: column;
        padding: 77px 0;
      }

      .footer-main {
        grid-template-columns: 1fr 1fr;
      }

      .footer-brand {
        grid-column: 1 / -1;
      }

      .footer-column:last-child {
        grid-column: 1 / -1;
      }
    }

    @media (max-width: 560px) {
      .container {
        width: calc(100% - 36px);
      }

      .navbar {
        height: 78px;
      }

      .nav-links {
        top: 77px;
      }

      .nav-book {
        display: none;
      }

