  <script>
    (() => {
      const navToggle = document.querySelector('.nav-toggle');
      const navLinks = document.querySelector('.nav-links');
      const navbar = document.querySelector('.navbar');

      function setMenu(open) {
        navToggle.setAttribute('aria-expanded', String(open));
        navToggle.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
        navLinks.classList.toggle('is-open', open);
        document.body.classList.toggle('menu-open', open && window.innerWidth <= 560);
      }

      navToggle.addEventListener('click', () => {
        setMenu(navToggle.getAttribute('aria-expanded') !== 'true');
      });

      navLinks.querySelectorAll('a').forEach(link => {
        link.addEventListener('click', () => setMenu(false));
      });

      document.addEventListener('click', event => {
        if (navToggle.getAttribute('aria-expanded') === 'true' && !navbar.contains(event.target)) {
          setMenu(false);
        }
      });

      document.addEventListener('keydown', event => {
        if (event.key === 'Escape' && navToggle.getAttribute('aria-expanded') === 'true') {
          setMenu(false);
          navToggle.focus();
        }
      });

      window.addEventListener('resize', () => {
        if (window.innerWidth > 900) setMenu(false);
      });

      const dialog = document.getElementById('booking-dialog');
      const form = document.getElementById('booking-form');
      const success = document.getElementById('booking-success');
      const selectedFare = document.getElementById('selected-fare');
      const departureSelect = document.getElementById('booking-departure');
      const dateInput = document.getElementById('booking-date');
      const passengersSelect = document.getElementById('booking-passengers');
      const successSummary = document.getElementById('success-summary');
      let lastTrigger = null;

      const localToday = new Date(Date.now() - new Date().getTimezoneOffset() * 60000)
        .toISOString()
        .split('T')[0];
      dateInput.min = localToday;

      function closeDialog() {
        if (typeof dialog.close === 'function') {
          dialog.close();
        } else {
          dialog.removeAttribute('open');
          if (lastTrigger) lastTrigger.focus();
        }
      }

      document.querySelectorAll('[data-book]').forEach(button => {
        button.addEventListener('click', () => {
          lastTrigger = button;
          selectedFare.textContent = button.dataset.book || 'Private Cabin';
          departureSelect.value = button.dataset.departure || '21:40';
          form.hidden = false;
          success.hidden = true;
          setMenu(false);

          if (typeof dialog.showModal === 'function') {
            if (!dialog.open) dialog.showModal();
          } else {
            dialog.setAttribute('open', '');
          }
        });
      });

      document.querySelectorAll('[data-close-dialog]').forEach(button => {
        button.addEventListener('click', closeDialog);
      });

      dialog.addEventListener('click', event => {
        if (event.target === dialog) closeDialog();
      });

      dialog.addEventListener('close', () => {
        if (lastTrigger) lastTrigger.focus();
      });

      form.addEventListener('submit', event => {
        event.preventDefault();

        const date = new Date(dateInput.value + 'T12:00:00');
        const formattedDate = new Intl.DateTimeFormat('en', {
          weekday: 'short',
          month: 'short',
          day: 'numeric',
          year: 'numeric'
        }).format(date);

        const departureText = departureSelect.options[departureSelect.selectedIndex].textContent;
        const passengerCount = passengersSelect.value;
        const passengerLabel = passengerCount === '1' ? 'passenger' : 'passengers';

        successSummary.textContent =
          selectedFare.textContent + ' · ' + passengerCount + ' ' + passengerLabel +
          '\n' + formattedDate + ' · ' + departureText;
        successSummary.style.whiteSpace = 'pre-line';

        form.hidden = true;
        success.hidden = false;
        success.focus();
      });

      document.getElementById('year').textContent = new Date().getFullYear();
    })();
  </script>
</body>
</html>
